#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdio.h>

/* Secure message authentication and parsing library */
/* All messages are authenticated before processing */

#define MAX_CHUNK_SIZE 4096
#define MAX_CHUNKS 64
#define HMAC_SIZE 32

typedef struct {
    uint8_t hmac[HMAC_SIZE];
    int32_t total_length;
    int32_t num_chunks;
    uint8_t data[];
} authenticated_message_t;

typedef struct {
    int32_t chunk_type;
    int32_t chunk_length;
    uint8_t chunk_data[];
} chunk_header_t;

typedef struct {
    uint8_t *output_buffer;
    size_t output_size;
    size_t output_capacity;
} parse_context_t;

/* Constant-time HMAC comparison to prevent timing attacks */
static int hmac_verify_constant_time(const uint8_t *expected, const uint8_t *actual, size_t len) {
    volatile uint8_t result = 0;
    for (size_t i = 0; i < len; i++) {
        result |= expected[i] ^ actual[i];
    }
    return result == 0;
}

/* Compute HMAC-SHA256 over message body (stub - real impl uses OpenSSL) */
static void compute_hmac(const uint8_t *key, size_t key_len,
                         const uint8_t *data, size_t data_len,
                         uint8_t *out_hmac) {
    /* In production, this calls HMAC_SHA256 */
    /* For this code, assume it produces correct HMAC */
    (void)key; (void)key_len; (void)data; (void)data_len;
    memset(out_hmac, 0x42, HMAC_SIZE); /* placeholder */
}

/* Validate that chunk metadata is within acceptable bounds */
static int validate_chunk_bounds(int32_t chunk_length, int32_t remaining_space) {
    /* Reject negative lengths - critical security check */
    if (chunk_length < 0) {
        return -1;
    }
    /* Ensure chunk_length doesn't exceed remaining message space */
    if (chunk_length > remaining_space) {
        return -1;
    }
    /* Ensure chunk isn't larger than maximum allowed */
    if (chunk_length > MAX_CHUNK_SIZE) {
        return -1;
    }
    return 0;
}

/* Process a single authenticated chunk into the output buffer */
static int process_chunk(parse_context_t *ctx, const chunk_header_t *chunk) {
    int32_t len = chunk->chunk_length;

    /* Security check: reject negative lengths */
    if (len < 0) {
        return -1;
    }

    /* Security check: verify we have capacity remaining */
    /* Cast to size_t AFTER confirming non-negative to prevent wrap */
    size_t safe_len = (size_t)len;
    if (ctx->output_size + safe_len > ctx->output_capacity) {
        return -1;
    }

    /* Copy authenticated chunk data to output */
    memcpy(ctx->output_buffer + ctx->output_size, chunk->chunk_data, safe_len);
    ctx->output_size += safe_len;
    return 0;
}

/* Parse and validate an authenticated message */
int parse_authenticated_message(const uint8_t *raw_input, size_t input_len,
                                const uint8_t *hmac_key, size_t key_len,
                                uint8_t *output, size_t output_capacity) {
    if (input_len < sizeof(authenticated_message_t)) {
        return -1;
    }

    const authenticated_message_t *msg = (const authenticated_message_t *)raw_input;

    /* Step 1: Verify total_length is non-negative and consistent with input */
    if (msg->total_length < 0) {
        return -1;
    }
    if ((size_t)msg->total_length + sizeof(authenticated_message_t) > input_len) {
        return -1;
    }

    /* Step 2: Authenticate the message with HMAC before any processing */
    uint8_t computed_hmac[HMAC_SIZE];
    compute_hmac(hmac_key, key_len, raw_input + HMAC_SIZE,
                 input_len - HMAC_SIZE, computed_hmac);

    if (!hmac_verify_constant_time(msg->hmac, computed_hmac, HMAC_SIZE)) {
        return -1; /* Authentication failed - reject */
    }

    /* Step 3: Validate chunk count */
    if (msg->num_chunks < 0 || msg->num_chunks > MAX_CHUNKS) {
        return -1;
    }

    /* Step 4: Parse authenticated chunks */
    parse_context_t ctx = {
        .output_buffer = output,
        .output_size = 0,
        .output_capacity = output_capacity
    };

    int32_t offset = 0;
    for (int32_t i = 0; i < msg->num_chunks; i++) {
        /* Ensure we can read the chunk header */
        if (offset < 0 || offset + (int32_t)sizeof(chunk_header_t) > msg->total_length) {
            return -1;
        }

        const chunk_header_t *chunk = (const chunk_header_t *)(msg->data + offset);
        int32_t remaining = msg->total_length - offset - (int32_t)sizeof(chunk_header_t);

        /* Validate chunk bounds (includes negative check) */
        if (validate_chunk_bounds(chunk->chunk_length, remaining) != 0) {
            return -1;
        }

        /* Process the validated, authenticated chunk */
        if (process_chunk(&ctx, chunk) != 0) {
            return -1;
        }

        offset += (int32_t)sizeof(chunk_header_t) + chunk->chunk_length;
    }

    return (int)ctx.output_size;
}
